import {oilMechanisms,priceComparison} from './situation-data.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export function reportImpactMarkup(report,oil) {
  const channels=oilMechanisms(report),eventDate=report.eventDate;
  const prices=(oil?.series||[]).map(series=>({name:series.name,last:series.observations?.at(-1),comparison:priceComparison(series.observations||[],eventDate)}));
  return `<section class="report-impact" aria-label="Oil relevance"><h3>Why it could matter for oil</h3><p class="detail-meta">Potential channels suggested by the available text · effects are not measured.</p>${channels.length?channels.slice(0,3).map(channel=>`<div class="evidence-channel"><strong>${esc(channel.name)}</strong><p>${esc(channel.explanation)}</p></div>`).join(''):'<p>No direct oil-supply or transport channel is established by this headline. Its regional relevance alone does not establish an oil-market effect.</p>'}<h3>What would strengthen the assessment</h3><p>${esc(report.watch||'Look for dated operator or official confirmation, the affected facility or route, the duration, and measured changes in loadings or transit. Compare independent accounts and subsequent corrections.')}</p><details class="report-price-context"><summary>Compare with dated oil observations</summary><p>${eventDate?'Exact event-day observations, when available.':'An event date is not established; the publication or discovery date is not used as a substitute.'} A price comparison does not attribute a move to this report.</p>${prices.map(({name,last,comparison})=>`<p><strong>${esc(name)}</strong> · ${comparison.onDate?`$${comparison.onDate.value.toFixed(2)} on ${esc(comparison.onDate.date)}`:last?`Latest available $${last.value.toFixed(2)} · ${esc(last.date)}`:'No observation available'}${comparison.delta!==null?` · ${comparison.delta>=0?'+':''}$${comparison.delta.toFixed(2)} from ${esc(comparison.before.date)}`:''}</p>`).join('')||'<p>Price observations are unavailable.</p>'}</details></section>`;
}
